mapper.update:
update s_apply_flow
uid = #{uid}, scene = #{scene}, status = #{status}, params = #{params}, audit_at = #{auditAt}, audit_msg = #{auditMsg}, create_at = #{createAt}, create_time = #{createTime}, update_time = #{updateTime},
where id = #{id}

mapper.select:
, (
WITH RECURSIVE cte AS (
select 0 as n, u.* from u_member u  join u_login ul on u.id = ul.uid and ul.type in (3) 

    and u.deleted = 0
     and u.id = #{uid}
     and ul.account = #{account} 
     and u.pid = #{pid}

union all
select  n+1,e.* from u_member e inner join `cte` c on e.pid = c.id and e.deleted = 0
) select distinct id, pid, n from `cte`
) b

    and a.uid = b.id
     and a.id = #{id}
     and a.scene = #{scene}
     and a.status = #{status}
     and a.create_at between #{extraParams.beginCreateAt} and #{extraParams.endCreateAt}

order by b.n, b.id

